delete from rounds
where image_url ilike '%picsum%'
   or image_url ilike '%placeholder%'
   or image_url ilike '%.jpg'
   or image_url ilike '%.svg'
   or location_name in (
     'Eiffel Tower Exposition Grounds',
     'Guadalajara',
     'Toronto',
     'Vancouver',
     'Montevideo',
     'La Paz',
     'Brasília',
     'Nairobi',
     'Algiers',
     'Accra'
   );

